function maxWorkload(workload, k) {
  const n = workload.length;
  const NEG = -1e15;
  const noBoost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  const boost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  noBoost[0][0] = workload[0];
  if (k >= 1) boost[0][1] = 2 * workload[0];
  for (let i = 1; i < n; i++) {
    for (let t = 0; t <= k; t++) {
      noBoost[i][t] = Math.max(noBoost[i-1][t], boost[i-1][t]) + workload[i];
    }
    for (let t = 1; t <= k; t++) {
      if (noBoost[i-1][t-1] > NEG) boost[i][t] = noBoost[i-1][t-1] + 2*workload[i];
    }
  }
  let best = NEG, bestT = 0, bestS = 0;
  for (let t = 0; t <= k; t++) {
    if (noBoost[n-1][t] > best) { best = noBoost[n-1][t]; bestT = t; bestS = 0; }
    if (boost[n-1][t] > best) { best = boost[n-1][t]; bestT = t; bestS = 1; }
  }
  // reconstruction would backtrack using saved states (omitted for brevity)
  return { maxValue: best, boostedIndices: [] };
}
```

## Why This Is Asked

This question tests your ability to design a dynamic programming solution for fixed-partition subproblems. It requires careful state definition, transition logic, and the ability to handle substring-to-integer conversion efficiently. Additionally, storing cut pointers enables reconstruction of the optimal partition.

## Key Concepts

- **Partition DP**: Divide a linear sequence into exactly k segments
- **On-the-fly value computation**: Accumulate digit values incrementally without re-parsing substrings
- **Reconstruction**: Maintain a parent pointer array to recover the cut positions
- **Time/Space tradeoffs**: O(n²k) time complexity with O(nk) space; can optimize to O(nk) space using rolling arrays

## Code Example

```javascript
function maxSumPartition(s, k) {
  const n = s.length;
  const digits = s.split('').map(Number);

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const cut = Array.from({ length: n + 1 }, () => Array(k + 1).fill(0));

  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= Math.min(i, k); t++) {
      let val = 0;
      for (let j = i; j >= t; j--) {
        val = digits[j - 1] * Math.pow(10, i - j) + val;
        if (dp[j - 1][t - 1] !== -Infinity) {
          const sum = dp[j - 1][t - 1] + val;
          if (sum > dp[i][t]) {
            dp[i][t] = sum;
            cut[i][t] = j - 1;
          }
        }
      }
    }
  }

  const cuts = [];
  let pos = n;
  for (let t = k; t >= 1; t--) {
    cuts.push(cut[pos][t]);
    pos = cut[pos][t];
  }

  return { maxSum: dp[n][k], cutPositions: cuts.reverse() };
}
```

## Why This Is Asked
Tests DP over subsequences with a fixed length and pairwise costs, plus explicit reconstruction. It moves beyond contiguous partitions by requiring last-step linkage through prior picks.

## Key Concepts
- Subsequence DP with fixed length
- Min-over-predecessor recurrence
- Path reconstruction via parent pointers
- Time/space trade-offs and practical optimizations

## Code Example
```javascript
function solve(A, m){
  const n=A.length;
  const dp=Array.from({length:n},()=>Array(m+1).fill(Infinity));
  const par=Array.from({length:n},()=>Array(m+1).fill(-1));
  for(let i=0;i<n;i++) dp[i][1]=0;
  for(let t=2;t<=m;t++){
    for(let i=t-1;i<n;i++){
      for(let j=t-2;j<i;j++){
        const c=dp[j][t-1]+Math.abs(A[i]-A[j]);
        if(c<dp[i][t]){ dp[i][t]=c; par[i][t]=j; }
      }
    }
  }
  let best=Infinity,bestI=-1;
  for(let i=m-1;i<n;i++){ if(dp[i][m]<best){ best=dp[i][m]; bestI=i; } }
  const path=[];
  let cur=bestI, t=m;
  while(t>=1){
    path.push(cur);
    cur=par[cur][t];
    t--;
  }
  path.reverse();
  return {cost:best, indices:path};
}
```

